interface User {
  id: number;
  email: string;
  role: "admin" | "guest";
}

function createUser(id: number, role?: "admin" | "guest"): User {
  return {
    id,
    email: `user_${id}@test.com`,
    role: role ?? "guest",
  };
}

const adminUser = createUser(5, "admin");
const guestUser = createUser(6);
const result = `${adminUser.email} | ${guestUser.role}`;
